"""Construct period strips and finite rosettes of congruent polygons, XIV p. 328."""
import argparse
import json
from math import cos,pi,sin,sqrt
from symmetry_applications import pattern,clear_pattern_names
from translations_and_rotations import lesson
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/tiling-symmetries.json'


def row(title,kind,b,h):
    if kind=='tri':
        group=[[(0,0),(b,0),(b,h)],[(0,0),(b,h),(0,h)]]
        period=b
    elif kind=='diamond':
        run=b/2
        group=[[(0,0),(b,0),(b+run,h),(run,h)]]
        period=b
    else:
        a=b-2
        shift=(b-a)/2
        up=[(0,0),(b,0),(b-shift,h),(shift,h)]
        down=[(2*b-shift-x,h-y) for x,y in up]
        group=[up,down]
        period=b+a
    cells=[[(x+j*period,y) for x,y in shape+[shape[0]]] for j in (-1,0,1) for shape in group]
    return pattern(title,cells,{'A':(0,0),'A′':(period,0)})


def rosette(title,triangle,n,reach):
    def radial(t):return reach*cos(t),reach*sin(t)
    cells=[]
    for i in range(n):
        alpha=2*pi*i/n
        a=radial(alpha)
        b=radial(alpha+(pi/3 if triangle else 2*pi/n))
        ring=[(0,0),a,b] if triangle else [(0,0),a,(a[0]+b[0],a[1]+b[1]),b]
        cells.append(ring+[ring[0]])
    named={'T':(0,0),'A':(reach,0),'A′':radial(2*pi/n)}
    return pattern(title,cells,{k:tuple(round(x,9) for x in v) for k,v in named.items()})


def frieze(part):
    if part=='а':
        kind='tri'
        noun='равных прямоугольных треугольников'
        proof='Начерти прямоугольник и его диагональ. Два полученных прямоугольных треугольника равны по двум катетам. Копируй прямоугольник вместе с той же диагональю в обе стороны, каждый раз на длину горизонтальной стороны. Перенос на этот вектор переводит каждую пару треугольников в следующую, а обратный перенос — в предыдущую. Поэтому бесконечный ряд вместе со всеми швами совпадает с собой.'
        steps=[('Собери прямоугольную ячейку','Первый рисунок построен на прямоугольнике ширины 2 и высоты 1. Диагональ делит его на два равных треугольника. У всех ячеек диагональ проведена в одном направлении.','Прямой угол находится в вершине прямоугольника, а диагональ служит гипотенузой.'),
               ('Совмести одноимённые вершины','Во втором рисунке ширина равна 3. Сдвиг от A к A′ переносит целую ячейку вместе с диагональю.','Длина диагонали отличается от горизонтального шага. Следи за одной и той же вершиной.'),
               ('Построй продолжение','В третьем рисунке ширина 4, высота 2. Представь ещё две ячейки справа и столько же слева. Вычисли путь при двух сдвигах вправо.','Если оборвать узор у границы рисунка, ненулевой перенос не сохранит полученную конечную фигуру.')]
        configs=[(2,1),(3,2),(4,2)];checks=[('Какова длина одного горизонтального сдвига во втором рисунке?','3','Шаг равен ширине ячейки.'),('Насколько сместится вершина за два шага в третьем рисунке?','8','Два шага по 4.')]
    elif part=='б':
        kind='diamond'
        noun='равных ромбов'
        proof='Возьми ромб с горизонтальной стороной AB. Приложи к нему второй такой же ромб переносом на вектор AB: правая наклонная сторона первого совпадёт с левой наклонной стороной второго. Продолжай переносы на этот же вектор и на противоположный. Все плитки равны как образы одной плитки. Весь ряд сохраняется переносом на AB и обратным переносом.'
        steps=[('Подготовь один ромб','На первом рисунке у ромба угол 60°. Его горизонтальная сторона имеет ту же длину, что и наклонная. Соседняя плитка начинается там, где кончается сторона первой.','Произвольный косой параллелограмм не обязательно ромб. Убедись в равенстве всех четырёх сторон.'),
               ('Повтори по стороне','Во втором рисунке длина стороны равна 3. От A до соответствующей вершины A′ следующего ромба ведёт горизонтальный перенос.','Для совмещения соседей не нужно поворачивать или отражать ромб.'),
               ('Смени длину стороны','На третьем рисунке сторона 4. Построй следующий ромб с тем же наклоном и определи перемещение вершины за два шага.','Расстояние за два периода измеряется между соответствующими вершинами первого и третьего ромбов.')]
        configs=[(2,sqrt(3)),(3,3*sqrt(3)/2),(4,2*sqrt(3))];checks=[('Какова длина переноса между соседними ромбами второго ряда?','3','Сдвиг равен стороне ромба.'),('Насколько сместится вершина после двух шагов третьего ряда?','8','Две стороны длины 4.')]
    else:
        kind='trap'
        noun='равных равнобедренных трапеций'
        proof='Поставь равнобедренную трапецию длинным основанием вниз. Поверни её на 180° вокруг середины правой боковой стороны: вторая трапеция примкнёт к первой этой стороной и будет обращена коротким основанием вниз. Вместе они составляют параллелограмм. Теперь повторяй всю пару переносом вдоль основания в обе стороны. Шаг равен сумме длин оснований трапеции: по нижней границе лежат длинное основание первой и короткое основание второй. Каждый шов переходит в соответствующий шов другой пары.'
        steps=[('Собери пару из одного образца','В первом рисунке основания равны 3 и 1. У второй трапеции они поменялись местами по высоте. Поворот сохраняет все стороны и углы.','Один перенос не перевернёт трапецию. Сначала построй пару с помощью полуоборота.'),
               ('Определи период пары','Во втором рисунке основания 4 и 2. Между A и A′ на нижней границе последовательно лежат оба эти основания.','Не удваивай только длинное основание: у соседней трапеции снизу короткое.'),
               ('Продолжи новый ряд','В третьем рисунке основания 5 и 3. Мысленно продолжи пары за оба края и вычисли длину двух последовательных переносов.','Половина пары после сдвига на половину периода не обязательно переводит большую нижнюю сторону в такую же сторону.')]
        configs=[(3,2),(4,2),(5,3)];checks=[('Каков шаг ряда при основаниях 4 и 2?','6','Сложи длины двух нижних отрезков пары.'),('Какова длина двух переносов при основаниях 5 и 3?','16','Один период равен 8.')]
    scenes=[row(t,kind,b,h) for t,(b,h) in zip(['Построй повторяющуюся ячейку','Найди один период','Повтори с новыми размерами'],configs,strict=True)]
    return clear_pattern_names(lesson(1279,part,328,'Построй фигуру с переносной симметрией из '+noun+'. Укажи точный вектор переноса и объясни, как продолжать построение.',proof,steps,scenes,checks,
       'Выбранный ненулевой перенос должен совместить со всей фигурой и границы плиток, и места их стыков. Проверь также, что у каждой плитки есть предшественница.',
       'Сначала собери одну ячейку, затем изобрази её копии перед ней и за ней.',
       'Видна часть бесконечного ряда. Перенос из A в A′ переводит всю ячейку в следующую.',
       'Опиши построение и докажи, что все требуемые плитки равны, а полученный бесконечный ряд обладает переносной симметрией.',refs=[125,127,128]))


def flower(part):
    triangle=part=='а'
    if triangle:
        examples=[(6,2),(3,3),(4,2)];noun='равных равносторонних треугольников'
        proof='Возьми точку T и проведи из неё шесть лучей с шагом 60°. На каждом отложи одно и то же расстояние. Соедини точки на соседних лучах. Получилась розетка из шести равносторонних треугольников: две стороны равны, угол между ними 60°, поэтому равна и третья сторона. Поворот на 60° вокруг T переводит каждый треугольник в следующий, последний — в первый. Можно брать треугольники с промежутками между ними, если шаг центровых поворотов остаётся постоянным.'
        steps=[('Построй собственный элемент','В первом рисунке шесть равносторонних треугольников сходятся при T. Угол при T у одного равен 60°.','Треугольник не становится равносторонним только от двух равных сторон: проверь и угол между ними.'),
               ('Оставь равные промежутки','Во второй розетке оставлены три равносторонних треугольника с одинаковыми промежутками. Найди поворот, ставящий весь треугольник на место следующего.','Угол внутри треугольника 60°, но шаг между соседними оставленными треугольниками больше.'),
               ('Измени число мотивов','Третья розетка состоит из четырёх равносторонних треугольников, пущенных по кругу с равным шагом. Найди угол между лучами TA и TA′.','Угол между началами соседних мотивов определяется их числом, даже если внутри мотива другой угол.')]
        checks=[('На сколько градусов надо повернуть вторую розетку, чтобы попасть к следующему треугольнику?','120','Три одинаковых шага составляют 360°.'),('Каков угловой шаг в розетке с четырьмя треугольниками?','90','Раздели полный оборот на четыре.')]
    else:
        examples=[(6,2),(5,2),(8,2)];noun='равных ромбов'
        proof='Раздели полный угол при T на шесть частей по 60°. На ограничивающих каждый сектор лучах отложи от T равные отрезки. Дострой их до параллелограмма: смежные стороны равны, значит, это ромб. Повтори построение во всех секторах с одной и той же длиной стороны. Поворот на 60° переводит каждый ромб в соседний, включая переход от последнего к первому. При другом числе равных секторов строят ромбы с соответствующим углом при T.'
        steps=[('Построй ромб в своём секторе','На первом чертеже каждый ромб начинается у T. Две его соседние стороны лежат на лучах под углом 60° и равны. Противоположные стороны проведены параллельно им.','Дальняя вершина ромба не лежит на окружности концов двух начальных сторон. Её находят пересечением параллелей.'),
               ('Поверни всю плитку','На втором рисунке пять одинаковых ромбов. Подели полный оборот на пять секторов. Один поворот переводит и ближние, и дальние вершины на место соседней плитки.','Учитывай дальнюю вершину, чтобы доказать совмещение целого ромба.'),
               ('Измени углы ромбов','В третьем рисунке восемь плиток. Найди угол при T, который требуется для построения каждой из них.','Сторона остаётся общей по длине, но угол при T теперь отличается от первого рисунка.')]
        checks=[('Каков поворот к следующему ромбу при пяти равных секторах?','72','Пятая часть полного угла.'),('Чему равен угол при T у ромба в восьмичастной розетке?','45','Восемь таких углов составляют 360°.')]
    scenes=[rosette(t,triangle,n,r) for t,(n,r) in zip(['Собери исходную розетку','Новый угловой шаг','Проверь ещё одно построение'],examples,strict=True)]
    return clear_pattern_names(lesson(1280,part,328,'Составь из '+noun+' фигуру с поворотной симметрией. Укажи центр и угол, переводящие все элементы на места.',proof,steps,scenes,checks,
       'Если n копий получены последовательными одинаковыми поворотами на 360°/n, очередной поворот замыкает обход и сохраняет всю фигуру.',
       'Выбери центр, построй первый мотив и повторяй один поворот, пока не вернёшься к исходному положению.',
       'T — центр всей розетки. Луч TA переходит в TA′ при повороте к следующему элементу.',
       'Опиши, как построен один элемент и его повёрнутые копии. Проверь их равенство и точное замыкание розетки.',refs=[126,127,128]))


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[*[frieze(p) for p in 'абв'],*[flower(p) for p in 'аб']]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
